1	/**
2	 * Theme composition regression tests.
3	 *
4	 * The design foundations are token data, not logic, so most of them can't break
5	 * in an interesting way. Two things genuinely can, and neither surfaces as a
6	 * build or type error:
7	 *
8	 *   1. A foundation stops reaching the composed theme (a missing key in
9	 *      `theme/index.ts`, or `extendTheme` clobbering a base scale).
10	 *   2. Someone remaps a Chakra scale key onto the Zimmermann value of the same
11	 *      name. Four of the five design-system font sizes collide with Chakra
12	 *      defaults (`md`, `xs`, `2xs`, `3xs`), and the base retail-react-app uses
13	 *      those names at ~199 call sites — so remapping silently restyles base
14	 *      components. See the `scale token collisions` block below.
15	 */
16	import React from 'react';
17	import { describe, expect, test } from 'vitest';
18	import { render } from '@testing-library/react';
19	import { Button, ChakraProvider, Text } from '@chakra-ui/react';
20	import theme from './index';
21	import { textStyles } from './foundation/typography';
22	import { globalStyles } from './globalStyles';
23	import { actionSizes, iconSizes } from './foundation/sizes';
24	import { zimmTokens } from './foundation/zimmTokens';
25	import { colors } from './foundation/colour';
26	import { borderWidths, spacing } from './foundation/spacing';
27	import { grid } from './foundation/gridSystem';
28	import { motion } from './foundation/motion';
29	
30	// Counts are drift detectors: both surfaces are ported 1:1 from the Handover
31	// design library, so a change here means a token was added or dropped.
32	const HANDOVER_TEXT_STYLE_COUNT = 22;
33	const HANDOVER_GLOBAL_CLASS_COUNT = 36;
34	
35	describe('foundations reach the composed theme', () => {
36	  test('brand colours resolve through their semantic aliases', () => {
37	    expect(theme.colors.text.default).toBe('#191919');
38	    expect(theme.colors.text.inverse).toBe('#ffffff');
39	    expect(theme.colors.background['07']).toBe('#ffffff');
40	    expect(theme.colors.action.primary.bgPressed).toBe('#454545');
41	    expect(theme.colors.ivory[400]).toBe('#f2e9e0');
42	  });
43	
44	  test('extendTheme merges rather than replaces the base colour scales', () => {
45	    // Regression guard: passing `colors` as a replacement instead of an override
46	    // would strip the base palette every base component still depends on.
47	    expect(theme.colors.gray).toBeTruthy();
48	    expect(theme.colors.blue).toBeTruthy();
49	  });
50	
51	  test('body and heading fonts resolve to Futura Round with the brand fallbacks', () => {
52	    expect(theme.fonts.body).toContain('Futura Round');
53	    expect(theme.fonts.heading).toContain('Futura Round');
54	    // Deliberate divergence from the Handover's bare "'Futura Round', sans-serif":
55	    // Century Gothic / Gill Sans render far closer to the brand than Arial.
56	    expect(theme.fonts.body).toContain('Century Gothic');
57	  });
58	
59	  test('space carries the named Zimmermann scale and keeps Chakra numerics', () => {
60	    expect(theme.space.xl).toBe('24px');
61	    expect(theme.space['3xs']).toBe('2px');
62	    expect(theme.space['7xl']).toBe('160px');
63	    expect(theme.space[4]).toBeTruthy();
64	  });
65	
66	  test('borderWidths and breakpoints are wired', () => {
67	    expect(theme.borderWidths.default).toBe('1px');
68	    expect(theme.breakpoints.md).toBe('48em');
69	    expect(theme.breakpoints.xl).toBe('80em');
70	  });
71	
72	  test('all Handover text styles are registered', () => {
73	    expect(Object.keys(textStyles)).toHaveLength(HANDOVER_TEXT_STYLE_COUNT);
74	    expect(Object.keys(theme.textStyles)).toHaveLength(HANDOVER_TEXT_STYLE_COUNT);
75	    expect(theme.textStyles.heading1.fontSize).toBe('24px');
76	    expect(theme.textStyles.navigation.textTransform).toBe('uppercase');
77	  });
78	
79	  test('all .zimm-* global classes reach styles.global', () => {
80	    const global = theme.styles.global as Record<string, unknown>;
81	    const zimmClasses = Object.keys(global).filter((key) => key.startsWith('.zimm-'));
82	    expect(zimmClasses).toHaveLength(HANDOVER_GLOBAL_CLASS_COUNT);
83	    expect(Object.keys(globalStyles)).toHaveLength(HANDOVER_GLOBAL_CLASS_COUNT);
84	  });
85	
86	  test('form-field classes are registered for the shared flush-border row', () => {
87	    // Ported from the Handover's tokens/form-fields.css; consumed by the text
88	    // input, select and search components.
89	    const global = theme.styles.global as Record<string, unknown>;
90	    expect(global['.zimm-form-row']).toBeTruthy();
91	    expect(global['.zimm-form-row-disabled']).toBeTruthy();
92	    expect(global['.zimm-form-row-inverse']).toBeTruthy();
93	    expect(global['.zimm-form-control']).toBeTruthy();
94	    expect(global['.zimm-form-control-inverse']).toBeTruthy();
95	  });
96	
97	  test('component overrides are registered', () => {
98	    // ListMenu in particular: the base component reads
99	    // theme.components.ListMenu.baseStyle directly, so a missing entry throws
100	    // at render rather than falling back.
101	    expect(theme.components.Button).toBeTruthy();
102	    expect(theme.components.Header).toBeTruthy();
103	    expect(theme.components.ListMenu).toBeTruthy();
104	  });
105	});
106	
107	describe('scale token collisions — Chakra keeps its own meanings', () => {
108	  test('fontSizes are NOT remapped to the Zimmermann scale', () => {
109	    // Design system: md 24px, xs 16px, 2xs 14px, 3xs 12px, 4xs 10px.
110	    // Chakra: md 16px, xs 12px, 2xs 10px, 3xs 7.2px — four collisions.
111	    // Type is set via `textStyle`, never a raw `fontSize` token, precisely so
112	    // these two scales never have to agree. If this test fails, someone has
113	    // remapped the scale and every base-component `fontSize` shifted with it.
114	    expect(theme.fontSizes.md).toBe('1rem');
115	    expect(theme.fontSizes.xs).toBe('0.75rem');
116	    expect(theme.fontSizes['2xs']).toBe('0.625rem');
117	  });
118	
119	  test('transition durations are NOT remapped to the Zimmermann motion scale', () => {
120	    // Zimmermann motion: fast 200ms, default 300ms, slow 500ms.
121	    // Chakra: fast 150ms, slow 300ms. Component overrides import the `motion`
122	    // constants directly instead, the same way they import FONT_MEDIUM.
123	    expect(theme.transition.duration.fast).toBe('150ms');
124	    expect(theme.transition.duration.slow).toBe('300ms');
125	  });
126	
127	  test('sizes are NOT remapped to the Zimmermann icon or action scales', () => {
128	    // theme.sizes.lg is Chakra's 32rem and backs w/h/boxSize across the base app.
129	    expect(theme.sizes.lg).toBe('32rem');
130	    // The brand dimensions live as importable constants instead.
131	    expect(iconSizes.lg).toBe('20px');
132	    expect(actionSizes.height.lg).toBe('52px');
133	  });
134	});
135	
136	/**
137	 * The design system is expressed twice: as Chakra values (`textStyles`) and as
138	 * CSS custom properties behind global classes (`.zimm-text-*`). Both are ported
139	 * from the same Handover source, so they must agree — but nothing structurally
140	 * forces that, and a one-sided edit would silently split them.
141	 *
142	 * Each pair below maps a `textStyle` key to its `.zimm-text-*` class. The class
143	 * side stores `var(--zimm-…)` references, so values are resolved through
144	 * `zimmTokens` before comparison.
145	 */
146	const TEXT_STYLE_TO_CLASS: ReadonlyArray<readonly [keyof typeof textStyles, string]> = [
147	  ['heading1Strong', '.zimm-text-h1-strong'],
148	  ['heading1', '.zimm-text-h1'],
149	  ['heading2', '.zimm-text-h2-strong'],
150	  ['heading3', '.zimm-text-h3-strong'],
151	  ['body1Strong', '.zimm-text-body1-strong'],
152	  ['body1', '.zimm-text-body1'],
153	  ['body2Strong', '.zimm-text-body2-strong'],
154	  ['body2', '.zimm-text-body2'],
155	  ['mobileBody1Strong', '.zimm-text-mobile-body1-strong'],
156	  ['mobileBody1', '.zimm-text-mobile-body1'],
157	  ['mobileBody2', '.zimm-text-mobile-body2'],
158	  ['label', '.zimm-text-label'],
159	  ['caption', '.zimm-text-caption'],
160	  ['linkLg', '.zimm-text-link-lg'],
161	  ['linkSm', '.zimm-text-link-sm'],
162	  ['button', '.zimm-text-btn-lg'],
163	  ['buttonSm', '.zimm-text-btn-sm'],
164	  ['productNames', '.zimm-text-product-name'],
165	  ['price', '.zimm-text-price'],
166	  ['navigation', '.zimm-text-nav'],
167	  ['footer', '.zimm-text-footer'],
168	  ['serif', '.zimm-text-serif'],
169	];
170	
171	/** Resolves a single `var(--zimm-…)` reference to its literal token value. */
172	function resolveToken(value: string | undefined): string | undefined {
173	  const match = value?.match(/^var\((--zimm-[a-z0-9-]+)\)$/);
174	  return match ? zimmTokens[match[1]] : value;
175	}
176	
177	describe('the Chakra and CSS-variable surfaces agree', () => {
178	  test('every textStyle has a matching .zimm-text-* class', () => {
179	    expect(TEXT_STYLE_TO_CLASS).toHaveLength(HANDOVER_TEXT_STYLE_COUNT);
180	
181	    const mappedStyles = TEXT_STYLE_TO_CLASS.map(([styleName]) => styleName).sort();
182	    expect(Object.keys(textStyles).sort()).toEqual(mappedStyles);
183	  });
184	
185	  test.each(TEXT_STYLE_TO_CLASS)('%s matches %s', (styleName, className) => {
186	    const style = textStyles[styleName] as Record<string, string | undefined>;
187	    const globalClass = (globalStyles as Record<string, Record<string, string | undefined>>)[className];
188	
189	    expect(globalClass).toBeTruthy();
190	
191	    // Compared per-property rather than wholesale: the class side carries extra
192	    // presentational declarations (colour, hover, focus) that the textStyle
193	    // deliberately does not.
194	    for (const property of ['fontSize', 'lineHeight', 'letterSpacing', 'fontWeight', 'textTransform'] as const) {
195	      if (style[property] === undefined && globalClass[property] === undefined) continue;
196	      expect(resolveToken(globalClass[property])).toBe(style[property]);
197	    }
198	  });
199	});
200	
201	/**
202	 * Every foundation value is written down twice: once as a TypeScript constant for
203	 * Chakra, once as a `--zimm-*` custom property for the global classes. Nothing
204	 * structurally forces the two to agree, so each pair is checked here.
205	 *
206	 * Notation is normalised before comparison — the CSS-variable side mirrors the
207	 * Handover source verbatim, which uses `white` and `#666` where the TypeScript
208	 * side spells the same colours `#ffffff` and `#666666`. Those are the same colour,
209	 * so they are treated as equal rather than churning a Handover-faithful file for
210	 * cosmetics.
211	 */
212	const CSS_COLOUR_KEYWORDS: Record<string, string> = { white: '#ffffff', black: '#000000' };
213	
214	function normaliseValue(value: string): string {
215	  const trimmed = value.trim().toLowerCase().replace(/\s+/g, ' ');
216	  const keyword = CSS_COLOUR_KEYWORDS[trimmed];
217	  if (keyword) return keyword;
218	
219	  const shorthand = trimmed.match(/^#([0-9a-f])([0-9a-f])([0-9a-f])$/);
220	  if (shorthand) {
221	    const [, r, g, b] = shorthand;
222	    return `#${r}${r}${g}${g}${b}${b}`;
223	  }
224	
225	  return trimmed === '0' ? '0px' : trimmed;
226	}
227	
228	const kebab = (value: string) => value.replace(/([A-Z])/g, '-$1').toLowerCase();
229	
230	// Token paths whose CSS-variable name doesn't follow the mechanical
231	// `group.camelCase` -> `group-kebab-case` rule.
232	const COLOUR_NAME_OVERRIDES: Record<string, string> = {
233	  'background.01': 'bg-01',
234	  'background.02': 'bg-02',
235	  'background.03': 'bg-03',
236	  'background.04': 'bg-04',
237	  'background.05': 'bg-05',
238	  'background.06': 'bg-06',
239	  'background.07': 'bg-07',
240	  'status.errorBackground': 'status-error-bg',
241	};
242	
243	// border.error has no Handover counterpart — it was added for form validation and
244	// is flagged as open with the UI designer, so it has no CSS-variable twin to match.
245	const COLOURS_WITHOUT_CSS_VAR = new Set(['border.error']);
246	
247	function flattenColours(node: unknown, path: string): Array<[string, string]> {
248	  if (typeof node === 'string') return [[path, node]];
249	  if (node !== null && typeof node === 'object') {
250	    return Object.entries(node as Record<string, unknown>).flatMap(([key, value]) =>
251	      flattenColours(value, path ? `${path}.${key}` : key),
252	    );
253	  }
254	  return [];
255	}
256	
257	describe('every foundation constant matches its --zimm-* twin', () => {
258	  const colourPairs = flattenColours(colors, '').filter(([path]) => !COLOURS_WITHOUT_CSS_VAR.has(path));
259	
260	  test('the colour palette is fully mapped', () => {
261	    // Guards the exclusion list: if a colour is added without a CSS-variable twin,
262	    // this count drifts and the per-token test below reports the missing name.
263	    expect(colourPairs.length).toBeGreaterThan(0);
264	    expect(COLOURS_WITHOUT_CSS_VAR.size).toBe(1);
265	  });
266	
267	  test.each(colourPairs)('colors.%s', (path, tsValue) => {
268	    const suffix = COLOUR_NAME_OVERRIDES[path] ?? kebab(path).replace(/\./g, '-');
269	    const varName = `--zimm-color-${suffix}`;
270	
271	    expect(zimmTokens[varName], `${varName} is missing from zimmTokens`).toBeDefined();
272	    expect(normaliseValue(zimmTokens[varName])).toBe(normaliseValue(tsValue));
273	  });
274	
275	  // Non-colour foundations. Listed explicitly rather than derived: the naming rules
276	  // differ per category (scale/size/motion/grid prefixes), so a table is clearer
277	  // than four separate transforms.
278	  const dimensionPairs: ReadonlyArray<readonly [string, string, string]> = [
279	    ...Object.entries(spacing).map(([key, value]) => [`spacing.${key}`, value, `--zimm-scale-${key}`] as const),
280	    ['borderWidths.default', borderWidths.default, '--zimm-border-width-default'],
281	    ...Object.entries(iconSizes).map(([key, value]) => [`iconSizes.${key}`, value, `--zimm-icon-size-${key}`] as const),
282	    ['actionSizes.height.lg', actionSizes.height.lg, '--zimm-size-action-height-lg'],
283	    ['actionSizes.height.md', actionSizes.height.md, '--zimm-size-action-height-md'],
284	    ['actionSizes.paddingX.lg', actionSizes.paddingX.lg, '--zimm-size-action-padding-h-lg'],
285	    ['actionSizes.paddingX.md', actionSizes.paddingX.md, '--zimm-size-action-padding-h-md'],
286	    ['actionSizes.gap', actionSizes.gap, '--zimm-size-action-gap'],
287	    ['grid.containerPadding.base', grid.containerPadding.base, '--zimm-grid-margin-mobile'],
288	    ['grid.containerPadding.md', grid.containerPadding.md, '--zimm-grid-margin-tablet'],
289	    ['grid.containerPadding.xl', grid.containerPadding.xl, '--zimm-grid-margin-desktop'],
290	    ['motion.duration.fast', motion.duration.fast, '--zimm-motion-duration-fast'],
291	    ['motion.duration.default', motion.duration.default, '--zimm-motion-duration-default'],
292	    ['motion.duration.slow', motion.duration.slow, '--zimm-motion-duration-slow'],
293	    ['motion.easing.standard', motion.easing.standard, '--zimm-motion-easing-standard'],
294	    ['motion.easing.slides', motion.easing.slides, '--zimm-motion-easing-slides'],
295	    ['motion.easing.fades', motion.easing.fades, '--zimm-motion-easing-fades'],
296	  ];
297	
298	  test.each(dimensionPairs)('%s', (_label, tsValue, varName) => {
299	    expect(zimmTokens[varName], `${varName} is missing from zimmTokens`).toBeDefined();
300	    expect(normaliseValue(zimmTokens[varName])).toBe(normaliseValue(tsValue));
301	  });
302	
303	  test('the font families are a single shared definition, not a copy', () => {
304	    // zimmTokens imports these from ./fonts, so they cannot drift by construction.
305	    expect(zimmTokens['--zimm-font-family-body']).toBe(theme.fonts.body);
306	    expect(zimmTokens['--zimm-font-family-heading']).toBe(theme.fonts.heading);
307	  });
308	});
309	
310	describe('rendered output', () => {
311	  test('textStyle applies the brand type style end to end', () => {
312	    const { getByTestId } = render(
313	      <ChakraProvider theme={theme}>
314	        <Text data-testid="body-1" textStyle="body1">
315	          Zimmermann
316	        </Text>
317	      </ChakraProvider>,
318	    );
319	
320	    const styles = window.getComputedStyle(getByTestId('body-1'));
321	    expect(styles.fontSize).toBe('16px');
322	    expect(styles.lineHeight).toBe('24px');
323	  });
324	
325	  test('Button renders square and uppercase from the theme override', () => {
326	    const { getByRole } = render(
327	      <ChakraProvider theme={theme}>
328	        <Button>Add to bag</Button>
329	      </ChakraProvider>,
330	    );
331	
332	    const styles = window.getComputedStyle(getByRole('button'));
333	    expect(styles.textTransform).toBe('uppercase');
334	    expect(styles.borderRadius).toBe('0px');
335	  });
336	});
