/**
 * Scratch probe (NOT part of the repo test suite).
 * Reproduces Storybook's mount: ChakraProvider + theme, with NO <Global> from
 * _app-config. Asks: do theme values reference --zimm-* vars that nothing defines?
 */
import React from 'react';
import { describe, expect, test } from 'vitest';
import { render } from '@testing-library/react';
import { Button, ChakraProvider } from '@chakra-ui/react';
import theme from '../../../../../Users/marcel.a.n.navarro/Dev/zimmermann-pwa/overrides/app/theme';

const collectEmittedCss = () =>
  Array.from(document.querySelectorAll('style'))
    .map((s) => s.textContent ?? '')
    .join('\n');

describe('storybook-equivalent mount (no zimmTokens <Global>)', () => {
  test('report unresolved --zimm-* references in emitted CSS', () => {
    render(
      <ChakraProvider theme={theme}>
        <Button variant="primary" size="lg">
          Add to bag
        </Button>
      </ChakraProvider>,
    );

    const css = collectEmittedCss();
    const referenced = [...new Set([...css.matchAll(/var\((--zimm-[a-z0-9-]+)\)/g)].map((m) => m[1]))].sort();
    const defined = [...new Set([...css.matchAll(/(--zimm-[a-z0-9-]+)\s*:/g)].map((m) => m[1]))].sort();
    const unresolved = referenced.filter((v) => !defined.includes(v));

    // eslint-disable-next-line no-console
    console.log(
      JSON.stringify(
        {
          referencedCount: referenced.length,
          definedCount: defined.length,
          unresolvedCount: unresolved.length,
          unresolvedSample: unresolved.slice(0, 25),
        },
        null,
        2,
      ),
    );

    expect(true).toBe(true);
  });
});

